<?php
namespace App\Controllers; use App\Core\{Application,Response,Session}; use App\Services\{AuthService,PermissionService,CsrfService};
final class AdminController{private AuthService $auth; public function __construct(private Application $app){$this->auth=new AuthService($app);} private function path():string{return '/'.$this->app->config()->get('admin_path');} public function login():string{return $this->app->view()->render('auth/login',['adminPath'=>$this->path(),'csrf'=>CsrfService::token(),'error'=>Session::flash('error')],'auth');} public function authenticate():never{if(!CsrfService::verify($_POST['_csrf']??null)){Session::flash('error','Güvenlik doğrulaması başarısız.');Response::redirect($this->path().'/login');} if(!$this->auth->attempt((string)($_POST['login']??''),(string)($_POST['password']??'')))Session::flash('error','Giriş bilgileri hatalı veya hesap pasif.'); Response::redirect($this->path());} public function logout():never{$this->auth->logout();Response::redirect($this->path().'/login');} public function dashboard():string{$u=$this->auth->require();(new PermissionService($this->app))->require($u,'dashboard.view');$pdo=$this->app->db()->pdo();$stats=[];foreach(['products','collections','subcollections','media','applications','contact_requests'] as $t){$stats[$t]=(int)$pdo->query("SELECT COUNT(*) FROM `$t`")->fetchColumn();}$logs=$pdo->query('SELECT a.*,u.username FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_user_id ORDER BY a.created_at DESC LIMIT 8')->fetchAll();return $this->app->view()->render('admin/dashboard',['user'=>$u,'stats'=>$stats,'logs'=>$logs,'adminPath'=>$this->path()],'admin');} public function module(string $module):string{$u=$this->auth->require();$map=['homepage'=>'homepage.manage','collections'=>'collections.view','subcollections'=>'subcollections.view','products'=>'products.view','applications'=>'applications.view','gallery'=>'media.view','media'=>'media.view','store'=>'store.manage','contacts'=>'contact_requests.view','seo'=>'seo.manage','menus'=>'menus.manage','settings'=>'settings.manage','users'=>'admins.view','roles'=>'admins.view','permissions'=>'admins.view','logs'=>'logs.view','backup'=>'system.backup','maintenance'=>'system.maintenance'];(new PermissionService($this->app))->require($u,$map[$module]??'dashboard.view');return $this->app->view()->render('admin/module',['module'=>$module,'user'=>$u,'adminPath'=>$this->path()],'admin');}}
